-- Demo data for the Project Estimator, DEMO tenants only (is_demo = true).
-- Run AFTER supabase/migrations/0131_estimator.sql. Idempotent.
-- GENERATED by scripts/gen-estimator-demo-seed.ts from the real engine; do not
-- edit by hand, change the starter template or the engine and regenerate.
--
-- What it does, per demo tenant:
--   1. turns the estimator module on (tenants.features.estimator = true);
--   2. adds the template "Precast villa (illustrative)" if the tenant has none by that name, or, if it
--      already has it, REFRESHES its inputs, rates and rules to the current starter
--      (E4 added the risk ranges and capacity rates; E5 renamed the groups and
--      options to plain words and offers the finish level as a quote alternative;
--      the template's version number is untouched);
--   3. adds ONE sample estimate "Sample villa, Riyadh (illustrative)" if it is not there yet, with
--      its computed lines, totals and 3D piece model already stored, so the
--      page shows everything without pressing Calculate. Margin 18%, VAT 15%.
--      If that sample estimate IS there and has no quote, it is REFRESHED the same
--      way: its figures, model and lines are replaced by the current starter's
--      (E5: the group names changed). Only that one demo estimate and only its own
--      lines; a sample that already has a quote is left alone; nothing else is
--      deleted.
-- Everything is illustrative: placeholder rates and rules, not a real price.

do $seed$
declare
  t uuid;
  tpl uuid;
  tpl_version int;
  acct uuid;
  cur text;
  est uuid;
  next_seq int;
  fresh boolean;
begin
  for t in select id from tenants where is_demo = true loop
    fresh := false;
    update tenants set features = coalesce(features, '{}'::jsonb) || '{"estimator": true}'::jsonb where id = t;

    if not exists (select 1 from estimate_templates where tenant_id = t and lower(name) = lower('Precast villa (illustrative)')) then
      insert into estimate_templates (tenant_id, name, description, trade, geometry, version, is_active, quote_granularity, inputs, rates, rules)
      values (
        t, 'Precast villa (illustrative)', 'ILLUSTRATIVE starter for a precast villa with a boundary wall, built from an exact piece model (wall panels, planks, beams, columns, stairs, boundary panels). All rates, ratios and rules are placeholders to demonstrate the estimator, not any company''s real prices or method. Duplicate it and replace them with your own.', 'precast', 'precast_villa', 1, true, 'group',
        $inputs$[{"key":"floors","label":"Number of floors","type":"number","default":2,"min":1,"max":4,"unit":"floors","section":"Building"},{"key":"built_up_area_m2","label":"Built-up area per floor","type":"number","default":150,"min":20,"max":2000,"unit":"m²","help":"Area of ONE floor; every floor is the same shape.","section":"Building"},{"key":"wall_perimeter_m","label":"External wall perimeter (one floor)","type":"number","default":50,"min":10,"max":500,"unit":"m","help":"With the area, this fixes the length and depth of the building.","section":"Building"},{"key":"wall_height_m","label":"Floor-to-floor wall height","type":"number","default":3,"min":2.4,"max":6,"unit":"m","section":"Building"},{"key":"ext_wall_thickness_m","label":"External wall thickness","type":"number","default":0.2,"min":0.1,"max":0.5,"unit":"m","section":"Building"},{"key":"finish_level","label":"External finish","type":"select","default":"standard","options":[{"key":"basic","label":"Basic","value":1},{"key":"standard","label":"Standard","value":1.08},{"key":"premium","label":"Premium","value":1.18}],"quote_alternatives":true,"help":"Standard adds 8% and Premium 18% to the concrete price of the faces that show.","section":"Building"},{"key":"include_stairs","label":"Include precast stairs","type":"boolean","default":true,"section":"Stairs"},{"key":"stair_flights","label":"Stair flights","type":"number","default":2,"min":0,"max":10,"unit":"flights","section":"Stairs"},{"key":"boundary_wall_length_m","label":"Boundary wall length","type":"number","default":60,"min":0,"max":2000,"unit":"m","section":"Boundary wall"},{"key":"boundary_wall_height_m","label":"Boundary wall height","type":"number","default":2.4,"min":1,"max":4,"unit":"m","section":"Boundary wall"}]$inputs$::jsonb,
        $rates$[{"key":"concrete_density_t_m3","label":"Concrete density","unit":"t/m³","value":2.4},{"key":"rebar_kg_per_m3","label":"Reinforcement per m³ of concrete","unit":"kg/m³","value":100},{"key":"insulated_area_share","label":"Share of external wall face that is insulated","unit":"fraction","value":0.9},{"key":"insert_spacing_m3","label":"Concrete served by one lifting insert","unit":"m³","value":1.2},{"key":"wastage_pct","label":"Wastage on concrete, steel and boards","unit":"%","value":0},{"key":"concrete_cost_m3","label":"Precast concrete, supplied and cast","unit":"per m³","value":330,"low":297,"high":412.5},{"key":"rebar_cost_kg","label":"Reinforcement steel, cut and bent","unit":"per kg","value":3.2,"low":2.72,"high":4.32},{"key":"insulation_cost_m2","label":"Insulation board","unit":"per m²","value":38,"low":34.2,"high":43.7},{"key":"fixing_cost_nr","label":"Lifting insert and fixings","unit":"per nr","value":65,"low":58.5,"high":74.75},{"key":"mould_cost_m3","label":"Mould usage","unit":"per m³","value":90},{"key":"labour_hours_per_m3","label":"Production labour hours per m³","unit":"h/m³","value":3.5,"low":3.18,"high":4.375},{"key":"labour_rate_hr","label":"Production labour rate","unit":"per h","value":18,"low":16.2,"high":21.6},{"key":"transport_load_capacity_t","label":"Transport capacity per load","unit":"t/load","value":25},{"key":"transport_cost_load","label":"Transport cost per load","unit":"per load","value":1800,"low":1620,"high":2340},{"key":"erection_cost_m3","label":"Erection","unit":"per m³","value":120,"low":108,"high":150},{"key":"overhead_factor","label":"Factory and yard overhead (share of production cost)","unit":"fraction","value":0.12},{"key":"cap_cast_m3_per_day","label":"Casting capacity","unit":"m³/day","value":18},{"key":"cap_trucks_loads_per_day","label":"Truck loads leaving the factory","unit":"loads/day","value":4},{"key":"cap_crane_m3_per_day","label":"Crane erection capacity","unit":"m³/day","value":24},{"key":"transport_start_day","label":"Transport starts on day","unit":"day","value":5},{"key":"erection_start_day","label":"Erection starts on day","unit":"day","value":6}]$rates$::jsonb,
        $rules$[{"code":"iw","group":"Structure (floors, beams, inner walls)","description":"Internal wall panels","uom":"m3","qty":"vol_IW","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"}},{"code":"sl","group":"Structure (floors, beams, inner walls)","description":"Hollow-core floor and roof planks","uom":"m3","qty":"vol_SL","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"slab"},{"code":"fr","group":"Structure (floors, beams, inner walls)","description":"Beams and columns","uom":"m3","qty":"vol_FR","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"beam"},{"code":"ew","group":"External walls and parapet","description":"External wall panels (insulated)","uom":"m3","qty":"vol_EW","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"wall_panel"},{"code":"pr","group":"External walls and parapet","description":"Parapet panels","uom":"m3","qty":"vol_PR","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"parapet_panel"},{"code":"fin","group":"External walls and parapet","description":"External finish premium (extra concrete cost on the faces that show)","uom":"m3","qty":"(vol_EW + vol_PR + vol_BW) * (finish_level - 1)","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"}},{"code":"st","group":"Stairs","description":"Stair flights","uom":"m3","qty":"vol_ST","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"stair"},{"code":"bw","group":"Boundary wall","description":"Boundary wall panels","uom":"m3","qty":"vol_BW","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"boundary_panel"},{"code":"rbr","group":"Production","descriptio