      where tenant_id = t and lower(name) = lower('Precast villa (illustrative)');
    end if;

    select id, version into tpl, tpl_version from estimate_templates where tenant_id = t and lower(name) = lower('Precast villa (illustrative)');

    if tpl is not null then
      select id into est from estimates where tenant_id = t and name = 'Sample villa, Riyadh (illustrative)' order by created_at limit 1;

      if est is null then
        select id into acct from accounts where tenant_id = t order by name limit 1;
        select nullif(config->>'currency', '') into cur from tenants where id = t;

        select coalesce(max(nullif(regexp_replace(ref, '\D', '', 'g'), '')::int), 0) + 1 into next_seq
        from estimates where tenant_id = t and ref ~ '^EST-\d+$';

        insert into estimates (tenant_id, ref, name, account_id, template_id, template_version, status, params, currency, margin_pct, totals, model, notes)
        values (
          t, 'EST-' || lpad(next_seq::text, 4, '0'), 'Sample villa, Riyadh (illustrative)', acct, tpl, tpl_version, 'draft',
          $params${"floors":2,"built_up_area_m2":150,"wall_perimeter_m":50,"wall_height_m":3,"ext_wall_thickness_m":0.2,"finish_level":"standard","include_stairs":true,"stair_flights":2,"boundary_wall_length_m":60,"boundary_wall_height_m":2.4}$params$::jsonb, cur, 18,
